def dec(d):
    d=d+'='*(-len(d)%4); return base64.urlsafe_b64decode(d).decode('utf-8','replace')
def walk(p,plain,html,files):
    if p.get('filename'): files.append(p['filename'])
    mt=p.get('mimeType',''); d=(p.get('body') or {}).get('data')
    if d and not p.get('filename'):
        if mt.startswith('text/html'): html.append(dec(d))
